return null;

// 들어오는 값: "LOUD", "INTRUSION", 그 외 등
const raw = String(msg.payload || "").trim();

// 1) 기본 UI용 텍스트 만들기
let uiText = "정상";
if (raw === "LOUD") {
    uiText = "🔊 큰 소리 감지!";
} else if (raw === "INTRUSION") {
