// 2) 현재 모드 / 외출 경과 시간 확인
const mode = flow.get("currentMode") || "HOME";
const awaySince = flow.get("awaySince");

// HOME이면 그냥 UI만 업데이트하고 끝
if (mode !== "AWAY" || !awaySince) {
    return [msgUi, null];
}

// 외출 후 경과 시간(ms)
const elapsed = Date.now() - awaySince;

// 외출한 지 1분 안 됐으면 아직 보안 모드 완전히 ON 아님
if (elapsed < 60 * 1000) {
    return [msgUi, null];
}

// LOUD/INTRUSION 아니면 침입 취급 안 함
if (raw !== "LOUD" && raw !== "INTRUSION") {
    return [msgUi, null];
}

// 3) 침입 상태 플래그로 텔레그램 스팸 방지
let already = flow.get("intrusionActive") || false;

let msgTelegram = null;
if (!already) {
    flow.set("intrusionActive", true);

    const now = new Date();
    const t = now.toLocaleString();  // “2025. 12. 05. 오후 7:03” 이런 느낌

