    // HTTP Request 노드용 메시지
    msgTelegram = {
        headers: { "Content-Type": "application/json" },
        payload: {
            chat_id:

,   // 네 채팅 ID
            text: text
        }
    };
}

// 1번 출력: 대시보드 (경보 상태 + 카드)
