return [msgUi, msgTelegram];

const AUTH_KEY = '<KMA_API_KEY>';

const now = new Date();
now.setMinutes(now.getMinutes() - 40);

function pad(n) {
    return n < 10 ? '0' + n : '' + n;
}

const y = now.getFullYear();
const m = pad(now.getMonth() + 1);
const d = pad(now.getDate());
const h = pad(now.getHours());

const base_date = '' + y + m + d;
const base_time = h + '00';

// 여기 추가
msg.base_date = base_date;
msg.base_time = base_time;

const params = {
    authKey: AUTH_KEY,
    numOfRows: '1000',
    pageNo: '1',
    base_date: base_date,
    base_time: base_time,
    nx: '61',
    ny: '120'
};

const esc = encodeURIComponent;
const qs = Object.keys(params)
    .map(k => k + '=' + esc(params[k]))
    .join('&');

msg.url = 'https://apihub.kma.go.kr/api/typ02/openApi/VilageFcstInfoService_2.0/getUltraSrtNcst?' + qs;

return msg;

function first(v) {
    return Array.isArray(v) ? v[0] : v;
}

const root = msg.payload || {};

const response = first(root.response);
if (!response) {
    node.warn("response 없음");
    return [null, null, null, null, null];
}

const body = first(response.body);
if (!body) {
    node.warn("body 없음");
    return [null, null, null, null, null];
}

const itemsWrap = first(body.items);
if (!itemsWrap || !itemsWrap.item) {
    node.warn("items/item 없음");
    return [null, null, null, null, null];
}

const items = itemsWrap.item;
const data = {};

for (let i = 0; i < items.length; i++) {
    const it = items[i];

    const cat = first(it.category);
    const val = first(it.obsrValue);

    if (cat != null) {
        data[cat] = val;
    }
}

node.status({ text: JSON.stringify(data) });

// 공통 데이터는 msg.weather에 넣고,
// 아래에서 출력 5개로 복사해서 뿌려줌
msg.weather = data;

// 각 출력으로 나갈 메시지 5개 만들기
const base = { ...msg };              // 얕은 복사
base.weather = data;                  // 확실하게 붙여줌

const out1 = { ...base }; // 기온
const out2 = { ...base }; // 습도
const out3 = { ...base }; // 강수량
const out4 = { ...base }; // 강수 형태
const out5 = { ...base }; // 바람

return [out1, out2, out3, out4, out5];

// msg.weather 에 실황 데이터가 들어온다고 가정
const w = msg.weather || {};

function num(v) {
    const f = parseFloat(v);
    return isNaN(f) ? null : f;
}

const temp = num(w.T1H);   // 기온
const hum = num(w.REH);   // 습도
const rn = num(w.RN1);   // 1시간 강수량
const pty = (w.PTY !== undefined ? Number(w.PTY) : null);
const wsd = num(w.WSD);   // 풍속
const vec = num(w.VEC);   // 풍향 (deg)

// 아이콘 + 색상도 같이 넣어서 카드별로 스타일 먹이게 할 것
// 1) 기온 카드 -------------------------------------------------
const cardTemp = {
    label: "외부 기온",
    value: temp !== null ? temp.toFixed(1) : "–",
    unit: "℃",
    desc: "",
    icon: "🌡️",
    color: "#ff6b6b"
};

// 2) 습도 카드 -------------------------------------------------
const cardHum = {
    label: "외부 습도",
    value: hum !== null ? hum.toFixed(0) : "–",
    unit: "%",
    desc: "",
    icon: "💧",
    color: "#4dabf7"
};

// 3) 강수량 카드 -----------------------------------------------
let rainText = "강수 없음";
let rainVal = "0.0";
if (rn !== null) {
    rainVal = rn.toFixed(1);
    if (rn > 0) rainText = rn.toFixed(1) + " mm";
}

const cardRn = {
    label: "1시간 강수량",
    value: rainVal,
    unit: "mm",
    desc: rainText,
    icon: "☔",
    color: "#74c0fc"
};

// 4) 강수 형태 카드 --------------------------------------------
let ptyText = "강수 없음";
if (pty !== null) {
    switch (pty) {
        case 0: ptyText = "강수 없음"; break;
        case 1: ptyText = "비"; break;
        case 2: ptyText = "비/눈"; break;
        case 3: ptyText = "눈"; break;
        case 5: ptyText = "빗방울"; break;
        case 6: ptyText = "빗방울/눈날림"; break;
        case 7: ptyText = "눈날림"; break;
    }
}

const cardPty = {
    label: "강수 형태",
    value: ptyText,
    unit: "",
    desc: "",
    icon: "🌧️",
    color: "#9775fa"
};

// 5) 바람 카드 -------------------------------------------------
let dirsKor = [
    "북", "북북동", "북동", "동북동",
    "동", "동남동", "남동", "남남동",
    "남", "남남서", "남서", "서남서",
    "서", "서북서", "북서", "북북서", "북"
];

let dirLabel = "방향 정보 없음";
if (vec !== null) {
    let idx = Math.floor((vec + 11.25) / 22.5);
    if (idx < 0) idx = 0;
    if (idx > 16) idx = 16;
    dirLabel = dirsKor[idx] + "풍";
}

let windMain = "정보 없음";
if (wsd !== null) {
    windMain = wsd.toFixed(1) + " m/s";
}

const cardWind = {
    label: "바람",
    value: windMain,
    unit: "",
    desc: dirLabel,
    icon: "🌬️",
    color: "#adb5bd"
};

// ★★ 출력 5개: 각 카드 하나씩 반환 ★★
return [
    { payload: cardTemp },  // 1: 기온
    { payload: cardHum },   // 2: 습도
    { payload: cardRn },    // 3: 강수량
    { payload: cardPty },   // 4: 강수 형태
    { payload: cardWind }   // 5: 바람
];

// JSON 파싱된 센서 값에서 기록 + 이벤트 카운트
// msg.payload: {temp, hum, light, gas, pir, loud, mode}

let p = msg.payload;
if (!p) return null;

let now = new Date();
let ts = now.getTime();

// ---- 1) 24시간 히스토리 (그래프용) ----
let history = flow.get('indoorHistory') || [];

history.push({
    t: ts,
    temp: Number(p.temp),
    hum: Number(p.hum)
});

// 24시간 이전 데이터는 버리기
let cutoff = ts - 24 * 60 * 60 * 1000;
history = history.filter(e => e.t >= cutoff);
flow.set('indoorHistory', history);

// ---- 2) 하루 이벤트 카운트 (캘린더용) ----
let dateKey = now.toISOString().slice(0, 10); // YYYY-MM-DD
let calendar = flow.get('indoorCalendar') || {};
let day = calendar[dateKey] || { discomfort: 0, gas: 0 };

let temp = Number(p.temp);
let hum = Number(p.hum);
let gas = Number(p.gas);

// 매우 단순한 쾌적 범위: 20~27도, 30~70% 밖이면 이벤트 1회
let discomfortEvent = false;
if (!isNaN(temp) && !isNaN(hum)) {
    if (temp < 20 || temp > 28 || hum < 30 || hum > 70) {
        discomfortEvent = true;
    }
}
if (discomfortEvent) {
    day.discomfort++;
}

// 가스 이벤트 (임계값은 센서 스케일 보고 조정)
if (!isNaN(gas) && gas > 1200) {
    day.gas++;
}

calendar[dateKey] = day;
flow.set('indoorCalendar', calendar);

// 그래프 업데이트용 트리거 메시지
return { topic: "update", payload: null };

// indoorHistory에서 기간별 데이터 뽑아서 Chart.js용 구조로 변환

let history = flow.get('indoorHistory') || [];
let range = flow.get('chartRange') || '6h';

if (msg && msg.topic === 'range') {
    if (typeof msg.payload === 'string') {
        range = msg.payload;
        flow.set('chartRange', range);
    }
} else if (!msg || msg.topic === 'update') {
    range = flow.get('chartRange') || '6h';
}

let now = Date.now();
let windowMs = 6 * 60 * 60 * 1000;
if (range === '1h') windowMs = 1 * 60 * 60 * 1000;
else if (range === '24h') windowMs = 24 * 60 * 60 * 1000;

let from = now - windowMs;

let labels = [];
let tempArr = [];
let humArr = [];
let comfortArr = [];

function comfortIndex(t, h) {
    if (isNaN(t) || isNaN(h)) return null;
    // 간단한 불쾌지수 근사식
    return 0.81 * t + 0.01 * h * (0.99 * t - 14.3) + 46.3;
}

history
    .filter(e => e.t >= from)
    .forEach(e => {
        let d = new Date(e.t);
        let label = d.toTimeString().slice(0, 5); // HH:MM
        labels.push(label);
        tempArr.push(e.temp);
        humArr.push(e.hum);
        comfortArr.push(comfortIndex(e.temp, e.hum));
    });

msg.topic = 'chart-data';
msg.payload = {
    range,
    labels,
    temp: tempArr,
    hum: humArr,
    comfort: comfortArr
};
return msg;

let now = new Date();
let year = now.getFullYear();
let month = now.getMonth(); // 0-based
let daysInMonth = new Date(year, month + 1, 0).getDate();
let firstDow = new Date(year, month, 1).getDay(); // 0=Sun

let calendar = flow.get('indoorCalendar') || {};
let days = [];

for (let d = 1; d <= daysInMonth; d++) {
    let dateObj = new Date(year, month, d);
    let iso = dateObj.toISOString().slice(0, 10);
    let info = calendar[iso] || { discomfort: 0, gas: 0 };
    let count = (info.discomfort || 0) + (info.gas || 0);
    let level = 0;
    if (count === 1) level = 1;
    else if (count === 2) level = 2;
    else if (count >= 3) level = 3;

    let dow = dateObj.getDay(); // 0..6
    let col = dow + 1;
    let row = Math.floor((firstDow + d - 1) / 7) + 1;

    days.push({
        day: d,
        iso: iso,
        level: level,
        col: col,
        row: row,
        discomfort: info.discomfort || 0,
        gas: info.gas || 0
    });
}

msg.payload = {
    year: year,
    month: month + 1,
    days: days
};
return msg;

// payload: "HOME" 또는 "AWAY" 들어옴
let mode = String(msg.payload || "").trim().toUpperCase();

// 이상한 값이면 무시
if (mode !== "HOME" && mode !== "AWAY") {
    return null;
}

// 현재 모드 저장
flow.set("currentMode", mode);

if (mode === "AWAY") {
    // 외출 시작 시각 기록
    flow.set("awaySince", Date.now());
    flow.set("intrusionActive", false);   // 침입 알림 플래그 리셋
} else {
    // 집으로 돌아옴
    flow.set("awaySince", null);
    flow.set("intrusionActive", false);
}

// MQTT out / 모드별 탭 전환 쪽으로 그대로 전달
return msg;

var p = ("" + msg.payload).trim();

// HOME 모드로 전환될 때 경보 상태를 "정상"으로 초기화
if (p === "HOME") {
    msg.payload = "정상";
    return msg;
}

// AWAY일 때는 경보 상태를 건드리지 않음
return null;

let mode = String(msg.payload || "").trim().toUpperCase();

// HOME / AWAY 아니면 무시
if (mode !== "HOME" && mode !== "AWAY") {
    return null;
}

// 여기 이름은 "탭 상단에 보이는 이름"이랑 1글자도 똑같아야 함
let tabName = (mode === "AWAY") ? "외출 모드" : "집 모니터링";

return {
    payload: {
        tab: tabName
    }
};

var w = msg.payload || {};

var t = parseFloat(w.T1H);
var reh = parseFloat(w.REH);
var rn1 = parseFloat(w.RN1);
var pty = (w.PTY !== undefined && w.PTY !== null) ? String(w.PTY) : "0";

if (isNaN(t)) t = 0;
if (isNaN(reh)) reh = 0;
if (isNaN(rn1)) rn1 = 0;

var outfitIcon = "🧥";
var main = "오늘의 옷 정보를 계산 중입니다.";
var sub = "외부 기온 데이터를 수신하면 자동으로 추천됩니다.";

if (!isNaN(t)) {
    if (t <= 0) {
        outfitIcon = "🧊";
        main = "한파 수준, 매우 따뜻하게 입기";
        sub = "두꺼운 패딩, 목도리, 장갑, 모자까지 준비하는 것이 좋습니다.";
    } else if (t <= 8) {
        outfitIcon = "🧥";
        main = "겨울 코트 / 패딩 추천";
        sub = "코트 또는 패딩 + 니트, 머플러 있으면 더 따뜻합니다.";
    } else if (t <= 15) {
        outfitIcon = "🧥";
        main = "간절기 아우터 필수";
        sub = "얇은 코트, 가디건, 후드 집업 정도가 적당합니다.";
    } else if (t <= 22) {
        outfitIcon = "👕";
        main = "가벼운 긴팔 위주";
        sub = "맨투맨, 셔츠, 가벼운 자켓 정도면 충분한 날씨입니다.";
    } else if (t <= 28) {
        outfitIcon = "🩳";
        main = "약간 더운 날씨, 시원하게";
        sub = "반팔 + 얇은 하의, 햇볕이 강하면 모자도 추천합니다.";
    } else {
        outfitIcon = "🔥";
        main = "한여름 날씨, 최대한 시원하게";
        sub = "통풍 잘 되는 반팔/반바지, 얇은 소재 위주로 입으세요.";
    }
}

var outfitMsg = {
    payload: {
        icon: outfitIcon,
        main: main,
        sub: sub,
        temp: t,
        hum: reh
    }
};

var umbrellaIcon = "☂️";
var uMain = "우산 정보를 계산 중입니다.";
var uSub = "강수량과 강수 형태를 기반으로 안내합니다.";

if (pty === "0" && rn1 === 0) {
    umbrellaIcon = "🌤";
    uMain = "우산 필요 없음";
    uSub = "강수 없음. 하늘만 한 번 확인하면 충분합니다.";
} else if (rn1 > 0 && rn1 < 1) {
    umbrellaIcon = "🌦";
    uMain = "약한 비, 접이식 우산 권장";
    uSub = "짧은 이동이면 모자/후드로도 버틸 수 있지만 우산 있으면 마음이 편합니다.";
} else if (rn1 >= 1) {
    umbrellaIcon = "☔";
    uMain = "우산 필수";
    uSub = "비가 제법 내릴 수 있는 날씨입니다. 튼튼한 우산을 준비하세요.";
}

var umbMsg = {
    payload: {
        icon: umbrellaIcon,
        main: uMain,
        sub: uSub,
        rn1: rn1,
        pty: pty
    }
};

return [outfitMsg, umbMsg];

var raw = String(msg.payload || "").trim();
if (!raw) {
    return null;
}

var now = new Date();
var todayStr = now.toISOString().slice(0, 10);
var storedDay = flow.get("awayEventsTodayDate");
var events = flow.get("awayEventsToday") || [];

if (storedDay !== todayStr) {
    events = [];
}

var h = String(now.getHours()).padStart(2, "0");
var m = String(now.getMinutes()).padStart(2, "0");
var timeLabel = h + ":" + m;

var label;
if (raw === "LOUD") {
    label = "큰 소리 감지";
} else if (raw === "INTRUSION") {
    label = "침입(인체 감지)";
} else {
    label = raw;
}

events.push({
    time: timeLabel,
    type: raw,
    label: label
});

if (events.length > 20) {
    events = events.slice(events.length - 20);
}

flow.set("awayEventsToday", events);
flow.set("awayEventsTodayDate", todayStr);

msg.payload = events;
return msg;

var topic = String(msg.topic || "");
var sleepOn = (topic === "home/mode/SLEEP");

global.set('sleepActive', sleepOn);

if (sleepOn) {
    global.set('sleepNoiseData', []);
    global.set('sleepStart', Date.now());
}

return msg;

var sleepActive = global.get('sleepActive') || false;
if (!sleepActive) {
    return null;
}

var data = global.get('sleepNoiseData') || [];

var loud = 0;
if (msg.payload && msg.payload.loud !== undefined) {
    loud = Number(msg.payload.loud) ? 1 : 0;
}

var point = {
    t: Date.now(),
    loud: loud
};

data.push(point);

if (data.length > 240) {
    data = data.slice(data.length - 240);
}

global.set('sleepNoiseData', data);

msg.payload = data;
return msg;
